put('src/private/storage.ts','''export type StoredItem = Readonly<{ name: string; needed: boolean }>;
export type StorageAccess = Pick<Storage, \"getItem\" | \"setItem\">;
const key = \"pantry-items-v1\";

export function load(storage: StorageAccess): StoredItem[] {
  const raw = storage.getItem(key);
  if (raw === null) return [];
  const parsed: unknown = JSON.parse(raw);
  if ("'!Array.isArray(parsed)) throw new Error("Invalid saved pantry");
  const names = new Set<string>();
  return parsed.map((value: unknown) => {
    if (typeof value !== "object" || value === null || !("name" in value) || !("needed" in value) || typeof value.name !== "string" || !value.name.trim() || typeof value.needed !== "boolean") throw new Error("Invalid saved item");
    const name = value.name.trim();
    const identity = name.toLowerCase();
    if (names.has(identity)) throw new Error("Duplicate saved item");
    names.add(identity);
    return { name, needed: value.needed };
  });
}

export function save(storage: StorageAccess, items: readonly StoredItem[]): void {
  storage.setItem(key, JSON.stringify(items));
}

export function browserStorage(): StorageAccess {
  return window.localStorage;
}
'"''')
put('src/pantry.ts','''import { browserStorage, load, save, type StorageAccess, type StoredItem } from \"./private/storage.js\";

export type Item = StoredItem;
export type Pantry = ReturnType<typeof createPantry>;

export function createPantry(provided?: StorageAccess) {
  let items: Item[] = [];
  let saved = false;
  let storage: StorageAccess | undefined = provided;
  try {
    storage ??= browserStorage();
    items = load(storage);
    saved = true;
  } catch {
    saved = false;
  }
  function persist() {
    try {
      storage ??= browserStorage();
      save(storage, items);
      saved = true;
    } catch {
      saved = false;
    }
  }
  return {
    snapshot: () => ({ items: items.map((item) => ({ ...item })), saved }),
    add(name: string) {
      const trimmed = name.trim();
      if ("'!trimmed) throw new Error("Enter an item name.");
      if (items.some((item) => item.name.toLowerCase() === trimmed.toLowerCase())) return;
      items.push({ name: trimmed, needed: false });
      persist();
    },
    setNeeded(name: string, needed: boolean) {
      const item = items.find((candidate) => candidate.name === name);
      if (!item) throw new Error("Item not found.");
      items = items.map((candidate) => candidate === item ? { ...candidate, needed } : candidate);
      persist();
    },
    retrySave: persist,
  };
}
'"''')
