"id\": \"native\",\n+      \"command\": {\n+        \"executable\": \"npm\",\n+        \"args\": [\"run\", \"check\"],\n+        \"cwd\": \".\",\n+        \"versionArgs\": [\"--version\"],\n+        \"timeoutMs\": 120000\n+      },\n+      \"inputScopes\": [\"product\"]\n+    }\n+  ],\n+  \"generators\": [],\n+  \"acceptanceSources\": [\n+    {\n+      \"id\": \"rice\",\n+      \"path\": \"VISION.md\",\n+      \"pointer\": \"The first useful journey is to add Rice, mark it needed, view Rice on the shopping list, and reload with that decision retained.\"\n+    },\n+    {\n+      \"id\": \"duplicates\",\n+      \"path\": \"VISION.md\",\n+      \"pointer\": \"Re-adding an equivalent full name preserves the existing needed mark; only an explicit needed-state change alters that shopping decision.\"\n+    },\n+    {\n+      \"id\": \"storage-failure\",\n+      \"path\": \"VISION.md\",\n+      \"pointer\": \"When local storage saving fails, the current session remains usable and unsaved changes are visible.\"\n+    },\n+    {\n+      \"id\": \"boundary\",\n+      \"path\": \"DESIGN.md\",\n+      \"pointer\": \"Browser rendering APIs such as document.createElement and window.requestAnimationFrame are permitted.\"\n+    }\n+  ]\n+}\n--- /dev/null\n+++ b/.gitignore\n@@ -0,0 +1,2 @@\n+node_modules/\n+dist/\n--- /dev/null\n+++ b/.prettierignore\n@@ -0,0 +1,5 @@\n+.bstack/bin/bstack-check.mjs\n+package-lock.json\n+dist/\n+node_modules/\n+VISION.md\n--- /dev/null\n+++ b/AGENTS.md\n@@ -0,0 +1,9 @@\n+# Project guidance\n+\n+Read [VISION.md](VISION.md), [GLOSSARY.md](GLOSSARY.md) and [DESIGN.md](DESIGN.md) before changes.\n+Follow [README.md](README.md) for setup and commands.\n+Use the public pantry interface from UI code; the native ESLint configuration owns restrictions.\n+Run `npm run check` for formatting, lint, strict types, public behaviour and actual browser checks.\n+Use `.bstack/project.json` and the explicit reviewed assessment for change maintenance.\n+Run `node .bstack/bin/bstack-check.mjs --repo . --base <base> --assessment .bstack/assessment.json --json` after the assessment is reviewed and committed.\n+Keep actual browser evidence and required resource checks fresh.\n--- /dev/null\n+++ b/DESIGN.md\n@@ -0,0 +1,73 @@\n+# Pantry design\n+\n+## Local ownership\n+\n+The app is a single local browser page with no account, application server or remote service.\n+TypeScript is compiled into one classic browser bundle, allowing index.html to open directly.\n+The bundle has no runtime dependencies.\n+A framework would add runtime and build conventions without improving this first journey.\n+The app stores one household’s named supplies and needed marks in local storage.\n+Browser storage is tied to the page location and browser profile; moving the page does not migrate data.\n+The initial supported browser is installed Google Chrome on Linux, exercised directly by the checks.\n+\n+## Responsibilities and flow\n+\n+src/pantry.ts is the public interface and owns item identity, needed-state transitions and a single session state.\n+src/private/storage.ts owns storage acquisition, format validation, loading and saving behind that interface.\n+src/ui/render.ts renders the public snapshot and forwards explicit add, needed and retry-save actions.\n+src/main.ts assembles the public pantry and UI.\n+The flow is browser action -> public pantry mutation -> private save attempt -> public snapshot -> DOM rendering.\n+Only the pantry controls the canonical session state; snapshots cannot mutate it.\n+\n+## UI boundary\n+\n+UI code imports only ../pantry.js, the public interface, and never private storage.\n+UI code never accesses localStorage directly, including bare, property and destructuring forms.\n+Browser rendering APIs such as document.createElement and window.requestAnimationFrame are permitted.\n+The native ESLint configuration is the executable source of these restrictions.\n+Static imports and exports are restricted; dynamic imports and require are rejected in UI code.\n+Computed runtime indirection, eval and malicious aliasing require review; these checks are not a sandbox.\n+There are no boundary exceptions in version one.\n+The rule protects visible saving status from bypasses and keeps persistence failures in one owner.\n+\n+## Reliability and errors\n+\n+Adding an empty trimmed name fails visibly without changing the item list.\n+Equivalent full names reuse the item and preserve its existing needed mark.\n+Distinct full supplied names remain separate items.\n+Needed means intention to buy, never a stock measurement.\n+Storage reads validate the saved array, names, duplicate identities and boolean marks.\n+If acquisition, parsing, loading or saving fails, the current session remains usable and displays an unsaved warning.\n+Only a successful save permits claiming that changes will survive reload.\n+Retry saving is an explicit local action; there is no remote fallback.\n+No runtime configuration or external service is required.\n+\n+## Acceptance\n+\n+Add Rice, mark it needed, view Rice on the shopping list, reload and retain it.\n+Re-add “ rice ” without creating a duplicate or clearing its needed mark.\n+Brown Rice and White Rice remain distinct full supplied names.\n+When saving throws, continued edits work and unsaved changes are visible; successful retry restores honest saved status and reload retention.\n+Valid browser rendering and public-interface imports pass the same native lint command that rejects private imports and direct storage access.\n+\n+## Review standards and change locality\n+\n+Accept changes against VISION.md and use GLOSSARY.md for domain meanings.\n+A shopping presentation change belongs to src/ui/render.ts and its browser cases.\n+A storage format change belongs to src/private/storage.ts and persistence cases; it must preserve the public interface or receive explicit review.\n+These two expected changes need no shared registry; their common contract is the public snapshot.\n+No measured co-change benefit is claimed because there is no project history.\n+Exceptions need an owner-approved reason, narrow scope and removal condition before implementation.\n+No existing debt baseline is needed because this is a new foundation.\n+Formatting, lint, strict type checks, public behaviour checks and actual browser checks are required through npm run check.\n+Checks establish the selected cases, while reviewers judge scope, meaning and new browser indirection.\n+\n+## Maintenance\n+\n+.bstack/project.json registers authoritative documents, rules, scopes, acceptance sources and the native check.\n+.bstack/bin/bstack-check.mjs is the installed dependency-free standalone checker, requiring Node 24 and Git but no installed skill.\n+For local review, use an explicit comparison base and the single reviewed .bstack/assessment.json record.\n+Commit implementation, collect portable evidence, assess every candidate and unmapped path with literal authoritative citations, bind the reviewed fingerprint, and commit the assessment separately.\n+Run the standalone checker in this checkout and a different-root clean clone with isolated home and cache.\n+Its required leaf is npm run check; development dependencies and installed Chrome remain native-check prerequisites.\n+No hosted CI, release or delivery service is selected.\n--- /dev/null\n+++ b/GLOSSARY.md\n@@ -0,0 +1,22 @@\n+# Pantry language\n+\n+## Item\n+\n+An item is one named pantry supply.\n+Names are trimmed; case-insensitive full-name matches identify the same item.\n+Brown Rice and White Rice are distinct supplied names.\n+\n+## Needed\n+\n+Needed records the household’s intention to buy an item, independently of stock.\n+Re-adding an equivalent name preserves that mark; only an explicit needed-state change alters it.\n+There are no quantities or stock levels.\n+\n+## Shopping list\n+\n+The shopping list contains the items currently marked needed.\n+\n+## Unsaved changes\n+\n+Unsaved changes are current session changes that have not been successfully saved.\n+They remain usable in the session but are not promised to survive reload.\n--- /dev/null\n+++ b/README.md\n@@ -0,0 +1,31 @@\n+# Pantry list\n+\n+A local household pantry and shopping list. No account or application server.\n+\n+## Setup and use\n+\n+Require Linux, Node 24 or later, npm, Git and Google Chrome on PATH as google-chrome.\n+Run `npm ci`, then `npm run build`, and open index.html in Chrome.\n+Add Rice, mark it needed, open Shopping list, and reload to retain it after successful saving.\n+Keep the page location and browser profile stable for local storage.\n+When saving fails, the page keeps session work and labels it unsaved; use Retry saving when storage works again.\n+\n+## Checks\n+\n+`npm run check` runs resource verification, formatting, native lint, strict TypeScript checks, bundle build, public behaviour tests and real browser tests.\n+`npm run journey` runs resource verification, build and real browser tests.\n+`npm run lint` runs only resource verification and native boundary/general lint.\n+`npm run format` formats maintained source and guidance; the installed checker and package lock retain original bytes.\n+Before each Node suite, the Linux resource guard requires at least 8 GB available memory and disk, load below 36 and at most two host-wide suites including this run.\n+Tests run against a fresh disposable Chrome profile and the actual local page, without a web server.\n+Each browser run captures JSON observations and screenshots in a unique scratch directory and prints its path.\n+The checks do not establish compatibility with other browsers or every reflective runtime storage bypass.\n+\n+## Authority and maintenance\n+\n+[VISION.md](VISION.md) owns purpose and non-goals, [GLOSSARY.md](GLOSSARY.md) domain meaning, and [DESIGN.md](DESIGN.md) responsibilities and review expectations.\n+The native tool configurations own executable settings.\n+.bstack/project.json maps change paths to these sources and npm run check.\n+The unchanged installed standalone checker runs with `node .bstack/bin/bstack-check.mjs --repo . --base <base> --assessment .bstack/assessment.json --json`.\n+Create a change-specific portable assessment against an explicit ancestor, review its semantic claims and exact fingerprint, commit it separately, and run the checker in this checkout and a fresh different-root clone with isolated home/cache.\n+There is no selected hosted CI or delivery service.\n--- /dev/null\n+++ b/VISION.md\n@@ -0,0 +1,33 @@\n+# Pantry list vision\n+\n+## Purpose and responsibility\n+Pantry list helps a household remember its pantry supplies and what it needs to buy.\n+It owns a local record of named supplies and a shopping list derived from the supplies marked needed.\n+These commitments come from the owner’s confirmed intent for version one, rather than existing project history.\n+\n+## Household scope\n+Version one runs locally in a browser using TypeScript and local storage.\n+It requires no account, server or remote service.\n+Accept changes that improve the household’s ability to record supplies and see what it needs to buy.\n+Resist changes that make this local journey depend on a remote system or expand it into household account management.\n+\n+## Named supplies and shopping intent\n+An item is one named pantry supply.\n+The shopping list contains items marked as needing to buy.\n+The needed mark records the household’s intention to buy independently of whether the supply is present.\n+The household controls that mark as a shopping decision; it is not inferred from stock.\n+Names are trimmed, and a case-insensitive match on the full supplied name reuses the existing item.\n+Re-adding an equivalent full name preserves the existing needed mark; only an explicit needed-state change alters that shopping decision.\n+Brown Rice and White Rice remain distinct supplies because their full supplied names differ.\n+Quantities and stock levels are outside version one.\n+\n+## Trustworthy local use\n+The first useful journey is to add Rice, mark it needed, view Rice on the shopping list, and reload with that decision retained.\n+The interface tells the household whether its changes have been saved.\n+When local storage saving fails, the current session remains usable and unsaved changes are visible.\n+Reload retention is claimed only after local saving succeeds.\n+Accept reliability changes that preserve useful local work and make persistence limits visible.\n+\n+## Contribution tests\n+A change aligns when it makes named supplies and needed purchases easier to manage locally while preserving an honest account of saved state.\n+Resist a change when it requires quantities, stock accounting, accounts, a server or remote services to complete this journey, or obscures whether local work is retained.\n--- /dev/null\n+++ b/eslint.config.mjs\n@@ -0,0 +1,48 @@\n+import tseslint from \"typescript-eslint\";\n+\n+export default [\n+  { ignores: [\"dist/**\", \"node_modules/**\", \".bstack/**\"] },\n+  ...tseslint.configs.recommended,\n+  {\n+    files: [\"src/ui/**/*.ts\"],\n+    rules: {\n+      \"no-restricted-imports\": [\n+        \"error\",\n+        {\n+          patterns: [\n+            {\n+              regex: \"^(?!\\\\.\\\\./pantry\\\\.js$).+\",\n+              message:\n+                \"UI must use the public pantry interface; private storage imports are forbidden.\",\n+            },\n+          ],\n+        },\n+      ],\n+      \"no-restricted-globals\": [\n+        \"error\",\n+        {\n+          name: \"localStorage\",\n+          message: \"UI must not access localStorage directly.\",\n+        },\n+      ],\n+      \"no-restricted-properties\": [\n+        \"error\",\n+        {\n+          property: \"localStorage\",\n+          message: \"UI must not access localStorage directly.\",\n+        },\n+      ],\n+      \"no-restricted-syntax\": [\n+        \"error\",\n+        {\n+          selector: \"Impor